+.pick .tag{display:inline-flex; align-items:center; gap:8px; margin-bottom:10px}
+.dot{width:9px; height:9px; border-radius:999px; background:var(--accent)}
+.pick .price{color:var(--primary)}
+
+.categories-grid{display:grid; grid-template-columns: repeat(5, 1fr); gap:14px}
+.category{
+  position:relative;
+  border-radius:22px;
+  overflow:hidden;
+  border:1px solid rgba(45, 106, 79, .14);
+  background:#fff;
+  box-shadow:var(--shadow-soft);
+  min-height:168px;
+  transform:translateZ(0);
+  transition:transform .16s ease, box-shadow .16s ease;
+}
+.category:hover{transform:scale(1.03); box-shadow:0 16px 34px rgba(17, 24, 39, .14)}
+.category .bg{position:absolute; inset:0}
+.category .bg img{width:100%; height:100%; object-fit:cover; filter:saturate(1.08) contrast(1.02)}
+.category .overlay{
+  position:absolute;
+  inset:0;
+  background:linear-gradient(180deg, rgba(17, 24, 39, .05), rgba(17, 24, 39, .54));
+  opacity:.0;
+  transition:opacity .18s ease;
+  display:flex;
+  align-items:flex-end;
+  padding:14px;
+}
+.category:hover .overlay{opacity:1}
+.category .overlay span{
+  color:#fff;
+  font-weight:950;
+  letter-spacing:-.3px;
+  font-family: ui-rounded, "Nunito", "Poppins", system-ui;
+  font-size:1.05rem;
+}
+.category:focus-visible{outline:3px solid var(--ring); outline-offset:4px}
+
+.panel{
+  border-radius:var(--radius);
+  background:rgba(255,255,255,.78);
+  border:1px solid rgba(45, 106, 79, .14);
+  box-shadow:var(--shadow-soft);
+  padding:16px;
+}
+.form-row{display:flex; gap:10px; flex-wrap:wrap}
+input[type="text"], input[type="email"]{
+  width:min(420px, 100%);
+  padding:12px 12px;
+  border-radius:14px;
+  border:1px solid rgba(45, 106, 79, .22);
+  background:rgba(255,255,255,.9);
+  font-weight:700;
+}
+input:focus{outline:3px solid var(--ring); border-color:rgba(45, 106, 79, .28)}
+
+.results{margin-top:14px; display:grid; gap:10px}
+.store{
+  display:grid;
+  grid-template-columns: 1.1fr 1.5fr .9fr .6fr;
+  gap:10px;
+  align-items:start;
+  padding:12px;
+  border-radius:16px;
+  background:#fff;
+  border:1px solid rgba(45, 106, 79, .14);
+}
+.store strong{font-weight:950}
+.store div{color:var(--muted); font-weight:650}
+.store .dist{color:var(--primary); font-weight:950}
+.helper{margin-top:10px; color:var(--muted); font-size:.95rem}
+
+.toast{
+  display:none;
+  margin-top:12px;
+  border-radius:16px;
+  padding:12px;
+  background:rgba(45, 106, 79, .08);
+  border:1px solid rgba(45, 106, 79, .18);
+  color:var(--primary-700);
+  font-weight:800;
+}
+.toast.show{display:block}
+
+footer{
+  padding:34px 0 46px;
+  color:rgba(31, 41, 55, .92);
+}
+.footer-grid{display:grid; grid-template-columns: 2fr 1fr 1fr 1fr; gap:14px}
+.footer-card{
+  border-radius:var(--radius);
+  background:rgba(255,255,255,.78);
+  border:1px solid rgba(45, 106, 79, .14);
+  padding:16px;
+  box-shadow:var(--shadow-soft);
+}
+.footer-card h3{margin:0 0 10px; font-family: ui-rounded, "Nunito", "Poppins", system-ui}
+.footer-card a{display:inline-flex; padding:7px 10px; border-radius:12px; color:rgba(31, 41, 55, .92); font-weight:750}
+.footer-card a:hover{background:rgba(244, 162, 97, .14)}
+.fineprint{margin-top:14px; color:var(--muted); font-weight:650}
+
+.sr-only{position:absolute; width:1px; height:1px; padding:0; margin:-1px; overflow:hidden; clip:rect(0,0,0,0); white-space:nowrap; border:0}
+
+@media (max-width: 980px){
+  .hero-grid{grid-template-columns: 1fr}
+  .highlights-grid{grid-template-columns: repeat(2, 1fr)}
+  .cards-grid{grid-template-columns: repeat(2, 1fr)}
+  .categories-grid{grid-template-columns: repeat(2, 1fr)}
+  .footer-grid{grid-template-columns: 1fr 1fr}
+  .navlinks{display:none}
+}
+@media (max-width: 560px){
+  .cards-grid{grid-template-columns: 1fr}
+  .categories-grid{grid-template-columns: 1fr}
+  .store{grid-template-columns: 1fr; gap:6px}
+  .brand{min-width:auto}
+}
+
*** End Patch
