+
+.carousel-viewport{
+  overflow:hidden;
+  border-radius:16px;
+}
+.carousel-track{
+  display:flex;
+  gap:14px;
+  padding:6px;
+  scroll-behavior:smooth;
+  overflow-x:auto;
+  scrollbar-width:none;
+}
