+  color:#fff;
+  font-weight:950;
+  letter-spacing:-.3px;
+  font-family: ui-rounded, "Nunito", "Poppins", system-ui;
+  font-size:1.05rem;
+}
+.category:focus-visible{outline:3px solid var(--ring); outline-offset:4px}
+
+.panel{
+  border-radius:var(--radius);
+  background:rgba(255,255,255,.78);
+  border:1px solid rgba(45, 106, 79, .14);
+  box-shadow:var(--shadow-soft);
+  padding:16px;
+}
+.form-row{display:flex; gap:10px; flex-wrap:wrap}
