+  font-weight:700;
+}
+input:focus{outline:3px solid var(--ring); border-color:rgba(45, 106, 79, .28)}
+
+.results{margin-top:14px; display:grid; gap:10px}
+.store{
+  display:grid;
+  grid-template-columns: 1.1fr 1.5fr .9fr .6fr;
+  gap:10px;
+  align-items:start;
+  padding:12px;
+  border-radius:16px;
+  background:#fff;
+  border:1px solid rgba(45, 106, 79, .14);
+}
